def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    candidates = []
    # Objects are solid rectangular panels whose cells may be corrupted by
    # other colors. Find fully occupied rectangles dominated by one color.
    for r0 in range(h):
        for r1 in range(r0 + 1, h):
            for c0 in range(w):
                for c1 in range(c0 + 1, w):
                    area = (r1-r0+1) * (c1-c0+1)
                    vals = [grid[r][c] for r in range(r0, r1+1) for c in range(c0, c1+1)]
                    if bg in vals:
                        continue
                    counts = Counter(vals)
                    color, count = counts.most_common(1)[0]
                    if count / area >= 0.60:
                        candidates.append((area, count, r0, r1, c0, c1, color))
    # Prefer the largest complete panel; discard smaller overlapping subwindows.
    candidates.sort(reverse=True)
    chosen = []
    occupied = set()
    for area, count, r0, r1, c0, c1, color in candidates:
        cells = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)}
        if cells & occupied:
            continue
        chosen.append((r0,r1,c0,c1,color))
        occupied.update(cells)
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r0,r1,c0,c1,color in chosen:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                out[r][c] = color
    return out
